  isNull(): this is RNull {
    return Module._TYPEOF(this.ptr) === RTypeMap.null;
  }

  isNa(): boolean {
    try {
      const result = parseEvalBare('is.na(x)', { x: this }) as RLogical;
      protect(result);
      return result.toBoolean();
