export class RNull extends RObject {
  constructor() {
    super(new RObjectBase(Module.getValue(Module._R_NilValue, '*')));
    return this;
  }

  toJs(): WebRDataJsNull {
    return { type: 'null' };
  }
}

export class RSymbol extends RObject {
