const dataBuffers: Uint8Array[][] = [];

function acquireDataBuffer(size: number): Uint8Array {
  const powerof2 = Math.ceil(Math.log2(size));
  if (!dataBuffers[powerof2]) {
    dataBuffers[powerof2] = [];
