  return new Proxy(RWorker.RObject, {
    construct: (_, args: WebRData[]) => newRObject(chan, objType, shelter, ...args),
    get: (_, prop: string | number | symbol) => {
      return targetMethod(chan, prop.toString());
    },
  }) as unknown as ProxyConstructor<T, R>;
}
